	//        "asset_id":"64bbff51-59d6-4b3c-9351-13ad85e3c752",
	//        "symbol":"BTCUSD",
	//        "asset_class":"crypto",
	//        "notional":null,
	//        "qty":"0.01",
	//        "filled_qty":"0",
	//        "filled_avg_price":null,
	//        "order_class":"",
	//        "order_type":"limit",
	//        "type":"limit",
	//        "side":"buy",
	//        "time_in_force":"day",
	//        "limit_price":"14000",
	//        "stop_price":null,
	//        "status":"accepted",
	//        "extended_hours":false,
	//        "legs":null,
	//        "trail_percent":null,
	//        "trail_price":null,
	//        "hwm":null,
	//        "commission":"0.42",
	//        "source":null
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(order, "symbol")
