func (this *Alpaca) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades
	//
	//   {
	//       "t":"2022-06-14T05:00:00.027869Z",
	//       "x":"CBSE",
	//       "p":"21942.15",
	//       "s":"0.0001",
	//       "tks":"S",
	//       "i":"355681339"
	//   }
	//
	// fetchMyTrades
	//
	//     {
	//         "id": "20221228071929579::ca2aafd0-1270-4b56-b0a9-85423b4a07c8",
	//         "activity_type": "FILL",
	//         "transaction_time": "2022-12-28T12:19:29.579352Z",
	//         "type": "fill",
	//         "price": "67.31",
	//         "qty": "0.07",
	//         "side": "sell",
	//         "symbol": "LTC/USD",
	//         "leaves_qty": "0",
	//         "order_id": "82eebcf7-6e66-4b7e-93f8-be0df0e4f12e",
	//         "cum_qty": "0.07",
	//         "order_status": "filled",
	//         "swap_rate": "1"
	//     },
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString2(trade, "S", "symbol")
	var symbol any = this.SafeSymbol(marketId, market)
	var datetime any = this.SafeString2(trade, "t", "transaction_time")
	var timestamp any = this.Parse8601(datetime)
	var alpacaSide any = this.SafeString(trade, "tks")
	var side any = this.SafeString(trade, "side")
	if IsTrue(IsEqual(alpacaSide, "B")) {
		side = "buy"
	} else if IsTrue(IsEqual(alpacaSide, "S")) {
		side = "sell"
	}
	var priceString any = this.SafeString2(trade, "p", "price")
	var amountString any = this.SafeString2(trade, "s", "qty")
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           this.SafeString2(trade, "i", "id"),
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"order":        this.SafeString(trade, "order_id"),
		"type":         nil,
		"side":         side,
		"takerOrMaker": "taker",
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"fee":          nil,
	}, market)
}

